const pptxgen = require("pptxgenjs");
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");

// Icon imports
const { FaSyringe, FaShieldAlt, FaGlobeAmericas, FaUsers, FaExclamationTriangle, FaBullseye, FaCheckCircle, FaChartLine, FaVirus, FaBaby, FaHeartbeat, FaArrowRight, FaClock, FaSkull, FaTimes } = require("react-icons/fa");

// Color palette — "Teal Trust" adapted for public health
const C = {
  navy:      "0B2545",
  deepTeal:  "13505B",
  teal:      "028090",
  seafoam:   "00A896",
  mint:      "02C39A",
  lightTeal: "D0F0ED",
  cream:     "F7F9F9",
  white:     "FFFFFF",
  darkText:  "1B2A4A",
  bodyText:  "2E4057",
  muted:     "6B7B8D",
  accent:    "E63946",
  gold:      "F4A261",
  lightGray: "E8ECEF",
  cardBg:    "F0F7F6",
};

const FONT_HEAD = "Georgia";
const FONT_BODY = "Calibri";

function renderIconSvg(IconComponent, color, size = 256) {
  return ReactDOMServer.renderToStaticMarkup(
    React.createElement(IconComponent, { color, size: String(size) })
  );
}

async function iconToBase64Png(IconComponent, color, size = 256) {
  const svg = renderIconSvg(IconComponent, color, size);
  const pngBuffer = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + pngBuffer.toString("base64");
}

function makeShadow(opts = {}) {
  return { type: "outer", color: "000000", blur: 6, offset: 2, angle: 135, opacity: 0.12, ...opts };
}

async function buildDeck() {
  let pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.author = "Public Health Analytics";
  pres.title = "The Power of Vaccination: From Smallpox Eradication to COVID-19 in Record Time";

  // Pre-render icons
  const icons = {
    syringe:   await iconToBase64Png(FaSyringe,   "#" + C.white, 256),
    shield:    await iconToBase64Png(FaShieldAlt,  "#" + C.white, 256),
    globe:     await iconToBase64Png(FaGlobeAmericas, "#" + C.white, 256),
    users:     await iconToBase64Png(FaUsers,      "#" + C.white, 256),
    warning:   await iconToBase64Png(FaExclamationTriangle, "#" + C.gold, 256),
    check:     await iconToBase64Png(FaCheckCircle, "#" + C.seafoam, 256),
    chart:     await iconToBase64Png(FaChartLine,  "#" + C.white, 256),
    virus:     await iconToBase64Png(FaVirus,      "#" + C.accent, 256),
    baby:      await iconToBase64Png(FaBaby,       "#" + C.teal, 256),
    heart:     await iconToBase64Png(FaHeartbeat,  "#" + C.accent, 256),
    arrow:     await iconToBase64Png(FaArrowRight, "#" + C.teal, 256),
    clock:     await iconToBase64Png(FaClock,      "#" + C.white, 256),
    skull:     await iconToBase64Png(FaSkull,      "#" + C.accent, 256),
    bullseye:  await iconToBase64Png(FaBullseye,   "#" + C.white, 256),
    syringeTeal: await iconToBase64Png(FaSyringe,  "#" + C.teal, 256),
    shieldTeal:  await iconToBase64Png(FaShieldAlt, "#" + C.teal, 256),
    globeTeal:   await iconToBase64Png(FaGlobeAmericas, "#" + C.teal, 256),
    checkWhite:  await iconToBase64Png(FaCheckCircle, "#" + C.white, 256),
    warningWhite: await iconToBase64Png(FaExclamationTriangle, "#" + C.white, 256),
    virusWhite: await iconToBase64Png(FaVirus, "#" + C.white, 256),
    usersTeal:  await iconToBase64Png(FaUsers, "#" + C.teal, 256),
    timesRed:   await iconToBase64Png(FaTimes, "#" + C.accent, 256),
  };

  // ============================================================
  // SLIDE 1: Title Slide
  // ============================================================
  let s1 = pres.addSlide();
  s1.background = { color: C.navy };

  // Decorative shape — large translucent circle
  s1.addShape(pres.shapes.OVAL, {
    x: 6.5, y: -1.5, w: 5.5, h: 5.5,
    fill: { color: C.deepTeal, transparency: 60 }
  });
  s1.addShape(pres.shapes.OVAL, {
    x: 7.5, y: 2.0, w: 4.0, h: 4.0,
    fill: { color: C.teal, transparency: 70 }
  });

  // Syringe icon
  s1.addImage({ data: icons.syringe, x: 0.8, y: 0.7, w: 0.55, h: 0.55 });

  s1.addText("THE POWER OF VACCINATION", {
    x: 0.8, y: 1.4, w: 7.5, h: 0.7,
    fontFace: FONT_HEAD, fontSize: 34, bold: true, color: C.white,
    charSpacing: 3, margin: 0
  });
  s1.addText("From Smallpox Eradication to COVID-19\nin Record Time", {
    x: 0.8, y: 2.15, w: 7.0, h: 0.9,
    fontFace: FONT_BODY, fontSize: 20, color: C.seafoam, margin: 0
  });

  // Thin accent line
  s1.addShape(pres.shapes.RECTANGLE, {
    x: 0.8, y: 3.25, w: 1.6, h: 0.04,
    fill: { color: C.mint }
  });

  s1.addText("A Data-Driven Overview for Public Health Professionals & Policy Analysts", {
    x: 0.8, y: 3.5, w: 6.5, h: 0.5,
    fontFace: FONT_BODY, fontSize: 13, color: C.muted, margin: 0
  });

  s1.addText("Spanning Two Centuries of Innovation: 1796 – 2020", {
    x: 0.8, y: 4.1, w: 6.0, h: 0.4,
    fontFace: FONT_BODY, fontSize: 12, italic: true, color: C.muted, margin: 0
  });

  s1.addText("Source: Our World in Data  •  ourworldindata.org/vaccination", {
    x: 0.8, y: 5.0, w: 6.0, h: 0.35,
    fontFace: FONT_BODY, fontSize: 10, color: C.muted, margin: 0
  });

  // ============================================================
  // SLIDE 2: Vaccine Timeline Acceleration — Horizontal Bar Chart
  // ============================================================
  let s2 = pres.addSlide();
  s2.background = { color: C.cream };

  // Top bar
  s2.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.teal }
  });

  s2.addText("From 100 Years to Under 1 Year", {
    x: 0.7, y: 0.3, w: 8.5, h: 0.55,
    fontFace: FONT_HEAD, fontSize: 28, bold: true, color: C.darkText, margin: 0
  });
  s2.addText("Vaccine Development Is Accelerating", {
    x: 0.7, y: 0.82, w: 8.5, h: 0.35,
    fontFace: FONT_BODY, fontSize: 15, color: C.muted, margin: 0
  });

  // Horizontal bar chart: disease name | bar showing years gap
  const timelineData = [
    { disease: "Typhoid Fever",  year: "1884 → 1989", gap: 105 },
    { disease: "Meningitis",     year: "1889 → 1981", gap: 92 },
    { disease: "Polio",          year: "1908 → 1955", gap: 47 },
    { disease: "Ebola",          year: "1976 → 2019", gap: 43 },
    { disease: "Whooping Cough", year: "1906 → 1948", gap: 42 },
    { disease: "Hepatitis B",    year: "1965 → 1981", gap: 16 },
    { disease: "Measles",        year: "1953 → 1963", gap: 10 },
    { disease: "COVID-19",       year: "2020 → 2020", gap: 1 },
  ];

  const barStartX = 2.8;
  const barMaxW = 6.2;
  const maxGap = 105;
  const barStartY = 1.4;
  const barH = 0.36;
  const barGap = 0.14;

  timelineData.forEach((d, i) => {
    const y = barStartY + i * (barH + barGap);
    const barW = Math.max((d.gap / maxGap) * barMaxW, 0.25);
    const isCovid = d.disease === "COVID-19";
    const barColor = isCovid ? C.accent : C.teal;

    // Disease label
    s2.addText(d.disease, {
      x: 0.3, y: y, w: 2.4, h: barH,
      fontFace: FONT_BODY, fontSize: 11, color: C.darkText,
      align: "right", valign: "middle", bold: isCovid, margin: 0
    });

    // Bar
    s2.addShape(pres.shapes.RECTANGLE, {
      x: barStartX, y: y + 0.04, w: barW, h: barH - 0.08,
      fill: { color: barColor },
      shadow: isCovid ? makeShadow() : undefined
    });

    // Gap label
    const label = isCovid ? "< 1 year" : `${d.gap} years`;
    s2.addText(label, {
      x: barStartX + barW + 0.12, y: y, w: 1.2, h: barH,
      fontFace: FONT_BODY, fontSize: 10, color: isCovid ? C.accent : C.muted,
      valign: "middle", bold: isCovid, margin: 0
    });
  });

  // COVID callout
  s2.addShape(pres.shapes.RECTANGLE, {
    x: 0.7, y: 5.0, w: 8.6, h: 0.45,
    fill: { color: C.accent, transparency: 90 },
    line: { color: C.accent, width: 1 }
  });
  s2.addText("COVID-19 vaccine developed in under 1 year — enabled by mRNA technology and genome sequencing", {
    x: 0.9, y: 5.0, w: 8.2, h: 0.45,
    fontFace: FONT_BODY, fontSize: 11, color: C.accent, valign: "middle", margin: 0
  });

  // ============================================================
  // SLIDE 3: US Disease Elimination Table
  // ============================================================
  let s3 = pres.addSlide();
  s3.background = { color: C.cream };

  s3.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.teal }
  });

  s3.addText("100% Case Reduction Achieved for Diphtheria, Polio, and Smallpox", {
    x: 0.7, y: 0.25, w: 8.6, h: 0.5,
    fontFace: FONT_HEAD, fontSize: 24, bold: true, color: C.darkText, margin: 0
  });
  s3.addText("Pre-vaccine vs. Post-vaccine Annual Rates in the United States (per million)", {
    x: 0.7, y: 0.72, w: 8.6, h: 0.3,
    fontFace: FONT_BODY, fontSize: 12, color: C.muted, margin: 0
  });

  const headerOpts = { fill: { color: C.deepTeal }, color: C.white, bold: true, fontFace: FONT_BODY, fontSize: 10, align: "center", valign: "middle" };
  const cellOpts = (highlight) => ({ fontFace: FONT_BODY, fontSize: 10, align: "center", valign: "middle", color: C.darkText, fill: { color: highlight ? C.lightTeal : C.white } });
  const greenBold = (highlight) => ({ fontFace: FONT_BODY, fontSize: 10, align: "center", valign: "middle", color: "0A7A4F", bold: true, fill: { color: highlight ? C.lightTeal : C.white } });

  const diseases = [
    ["Diphtheria",    "158",   "0",   "100%",  "13.7",  "100%",  true],
    ["Smallpox",      "250",   "0",   "100%",  "2.9",   "100%",  true],
    ["Acute Polio",   "141",   "0",   "100%",  "10",    "100%",  true],
    ["Measles",       "3,044", "0.2", "99.99%","2.5",   "100%",  true],
    ["Rubella",       "242",   "0.04","99.98%","0.09",  "100%",  true],
    ["Pertussis",     "1,534", "52",  "96.6%", "30.8",  "99.7%", false],
    ["Hepatitis A",   "465",   "51",  "89%",   "0.5",   "88.7%", false],
    ["Hepatitis B",   "273",   "44",  "83.9%", "1",     "83.6%", false],
    ["Pneumococcal",  "233",   "139", "40.5%", "24",    "31.3%", false],
  ];

  let tableRows = [
    [
      { text: "Disease", options: { ...headerOpts, align: "left" } },
      { text: "Pre-Vaccine\nCases", options: headerOpts },
      { text: "Post-Vaccine\nCases", options: headerOpts },
      { text: "Case\nReduction", options: headerOpts },
      { text: "Pre-Vaccine\nDeaths", options: headerOpts },
      { text: "Death\nReduction", options: headerOpts },
    ]
  ];

  diseases.forEach(([name, pre, post, caseRed, preDeath, deathRed, highlight]) => {
    const is100 = caseRed === "100%";
    tableRows.push([
      { text: name, options: { ...cellOpts(highlight), align: "left", bold: is100 } },
      { text: pre, options: cellOpts(highlight) },
      { text: post, options: is100 ? greenBold(highlight) : cellOpts(highlight) },
      { text: caseRed, options: caseRed === "100%" || parseFloat(caseRed) >= 99 ? greenBold(highlight) : cellOpts(highlight) },
      { text: preDeath, options: cellOpts(highlight) },
      { text: deathRed, options: deathRed === "100%" || parseFloat(deathRed) >= 99 ? greenBold(highlight) : cellOpts(highlight) },
    ]);
  });

