    { color: C.lightGray, label: "Unvaccinated (vulnerable)" },
    { color: C.accent, label: "Infected" },
  ];
  legItems.forEach((l, i) => {
    const lx = 0.7 + i * 3.1;
    s6.addShape(pres.shapes.OVAL, {
      x: lx, y: legY, w: 0.2, h: 0.2, fill: { color: l.color }
    });
    s6.addText(l.label, {
      x: lx + 0.3, y: legY, w: 2.5, h: 0.2,
      fontFace: FONT_BODY, fontSize: 10, color: C.bodyText, valign: "middle", margin: 0
    });
  });

  // Explanation text
  s6.addShape(pres.shapes.RECTANGLE, {
    x: 0.7, y: 4.75, w: 8.6, h: 0.65,
    fill: { color: C.lightTeal, transparency: 50 }
  });
  s6.addText([
    { text: "When enough people are vaccinated, pathogens cannot spread effectively — shielding ", options: { fontSize: 11, color: C.bodyText } },
    { text: "newborns, immunocompromised individuals, and cancer patients on chemotherapy", options: { fontSize: 11, color: C.bodyText, bold: true } },
    { text: " who cannot be vaccinated themselves.", options: { fontSize: 11, color: C.bodyText } },
  ], {
    x: 0.9, y: 4.78, w: 8.2, h: 0.6,
    fontFace: FONT_BODY, valign: "middle", margin: 0
  });

  // ============================================================
  // SLIDE 7: Remaining Challenges
  // ============================================================
  let s7 = pres.addSlide();
  s7.background = { color: C.cream };

  s7.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.gold }
  });

  s7.addText("Gaps Persist: Pneumococcal Disease Shows Only 40% Case Reduction", {
    x: 0.7, y: 0.25, w: 8.6, h: 0.55,
    fontFace: FONT_HEAD, fontSize: 24, bold: true, color: C.darkText, margin: 0
  });

  // 3 stat cards for diseases with incomplete control
  const statCards = [
    { disease: "Pneumococcal", caseRed: "40.5%", deathRed: "31.3%", severity: "high" },
    { disease: "Hepatitis A",  caseRed: "89%",   deathRed: "88.7%", severity: "med" },
    { disease: "Hepatitis B",  caseRed: "83.9%", deathRed: "83.6%", severity: "med" },
  ];

  statCards.forEach((sc, i) => {
    const cx = 0.7 + i * 3.05;
    const cy = 1.1;
    const cw = 2.8;
    const ch = 2.2;

    s7.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: cy, w: cw, h: ch,
      fill: { color: C.white },
      shadow: makeShadow()
    });
    // Top accent bar
    s7.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: cy, w: cw, h: 0.06,
      fill: { color: sc.severity === "high" ? C.accent : C.gold }
    });

    s7.addText(sc.disease, {
      x: cx + 0.2, y: cy + 0.2, w: cw - 0.4, h: 0.3,
      fontFace: FONT_BODY, fontSize: 14, bold: true, color: C.darkText, margin: 0
    });
    s7.addText(sc.caseRed, {
      x: cx + 0.2, y: cy + 0.6, w: cw - 0.4, h: 0.55,
      fontFace: FONT_HEAD, fontSize: 36, bold: true, color: sc.severity === "high" ? C.accent : C.gold, margin: 0
    });
    s7.addText("case reduction", {
      x: cx + 0.2, y: cy + 1.15, w: cw - 0.4, h: 0.25,
      fontFace: FONT_BODY, fontSize: 11, color: C.muted, margin: 0
    });
    s7.addText(sc.deathRed + " death reduction", {
      x: cx + 0.2, y: cy + 1.55, w: cw - 0.4, h: 0.25,
      fontFace: FONT_BODY, fontSize: 11, color: C.bodyText, margin: 0
    });
  });

  // Barrier cards
  const barrierY = 3.6;
  s7.addText("Key Barriers to Closing the Gap", {
    x: 0.7, y: 3.45, w: 8.6, h: 0.3,
    fontFace: FONT_BODY, fontSize: 14, bold: true, color: C.darkText, margin: 0
  });

  const barriers = [
    { icon: icons.globeTeal, title: "Access Gaps", desc: "Not everyone has access to vaccines globally" },
    { icon: icons.warningWhite, title: "Supply Shortages", desc: "Supply shortages put children at risk" },
    { icon: icons.usersTeal, title: "Trust Challenges", desc: "Poor scientific understanding reduces trust and uptake" },
  ];

  barriers.forEach((b, i) => {
    const bx = 0.7 + i * 3.05;

    s7.addShape(pres.shapes.RECTANGLE, {
      x: bx, y: barrierY, w: 2.8, h: 0.9,
      fill: { color: C.lightTeal }
    });
    s7.addShape(pres.shapes.RECTANGLE, {
      x: bx, y: barrierY, w: 0.05, h: 0.9,
      fill: { color: C.teal }
    });

    s7.addText(b.title, {
      x: bx + 0.2, y: barrierY + 0.08, w: 2.4, h: 0.3,
      fontFace: FONT_BODY, fontSize: 12, bold: true, color: C.darkText, margin: 0
    });
    s7.addText(b.desc, {
      x: bx + 0.2, y: barrierY + 0.4, w: 2.4, h: 0.4,
      fontFace: FONT_BODY, fontSize: 10, color: C.bodyText, margin: 0
    });
  });

  s7.addText("Compared to 100% elimination achieved for diphtheria, smallpox, and polio — these diseases demand continued investment.", {
    x: 0.7, y: 4.7, w: 8.6, h: 0.5,
    fontFace: FONT_BODY, fontSize: 11, italic: true, color: C.muted, margin: 0
  });

  // ============================================================
  // SLIDE 8: Key Takeaways & Call to Action
  // ============================================================
  let s8 = pres.addSlide();
  s8.background = { color: C.navy };

  s8.addText("Key Takeaways", {
    x: 0.7, y: 0.35, w: 8.6, h: 0.55,
    fontFace: FONT_HEAD, fontSize: 30, bold: true, color: C.white, margin: 0
  });
  s8.addText("Vaccines Have Eliminated Deadly Diseases — But the Job Isn't Done", {
    x: 0.7, y: 0.88, w: 8.6, h: 0.35,
    fontFace: FONT_BODY, fontSize: 14, color: C.seafoam, margin: 0
  });

  const takeaways = [
    { icon: icons.checkWhite, text: "Vaccines achieved 100% elimination of cases and deaths for diphtheria, smallpox, and polio in the US" },
    { icon: icons.clock, text: "Development timelines collapsed from over 100 years (typhoid) to under 1 year (COVID-19), driven by mRNA technology" },
    { icon: icons.shield, text: "Measles cases dropped to near zero across all 50 US states after the 1980 kindergarten vaccination mandate" },
    { icon: icons.globe, text: "Smallpox remains the only human disease eradicated through vaccination, certified in 1980" },
    { icon: icons.warningWhite, text: "Gaps persist: pneumococcal disease (40.5%), hepatitis A (89%), and hepatitis B (83.9%) need improved coverage" },
  ];

  takeaways.forEach((t, i) => {
    const ty = 1.5 + i * 0.65;

    s8.addShape(pres.shapes.OVAL, {
      x: 0.9, y: ty + 0.05, w: 0.4, h: 0.4,
      fill: { color: C.teal }
    });
    s8.addImage({ data: t.icon, x: 0.97, y: ty + 0.12, w: 0.26, h: 0.26 });

    s8.addText(t.text, {
      x: 1.5, y: ty, w: 7.5, h: 0.5,
      fontFace: FONT_BODY, fontSize: 13, color: C.white, valign: "middle", margin: 0
    });
  });

  // Call to action
  s8.addShape(pres.shapes.RECTANGLE, {
    x: 0.7, y: 4.45, w: 8.6, h: 0.85,
    fill: { color: C.deepTeal }
  });
  s8.addShape(pres.shapes.RECTANGLE, {
    x: 0.7, y: 4.45, w: 0.06, h: 0.85,
    fill: { color: C.mint }
  });
  s8.addText("CALL TO ACTION", {
    x: 1.0, y: 4.5, w: 8.0, h: 0.25,
    fontFace: FONT_BODY, fontSize: 10, bold: true, color: C.mint, charSpacing: 3, margin: 0
  });
  s8.addText("Global health systems must improve vaccine access, close supply gaps, and build public trust to replicate these successes for the diseases where the job remains unfinished.", {
    x: 1.0, y: 4.75, w: 8.0, h: 0.45,
    fontFace: FONT_BODY, fontSize: 12, color: C.lightTeal, margin: 0
  });

  // Write file
  await pres.writeFile({ fileName: "/app/output/final_deck.pptx" });
  console.log("Deck saved to /app/output/final_deck.pptx");
}

buildDeck().catch(err => { console.error(err); process.exit(1); });

